'use client';

import React, { useState, useEffect } from 'react';
import { Header } from './components/Header';
import { HeroSection } from './components/HeroSection';
import { ProductLookbookCards } from './components/ProductLookbookCards';
import { WomenHeroSection } from './components/WomenHeroSection';
import { WomenLookbookCards } from './components/WomenLookbookCards';
import { ProductListPage } from './components/ProductListPage';
import { ProductDetailPage } from './components/ProductDetailPage';
import { AboutPage } from './components/AboutPage';
import { ContactPage } from './components/ContactPage';
import { ProfilePage } from './components/ProfilePage';
import { CheckoutPage } from './components/CheckoutPage';
import { Footer } from './components/Footer';
import { CollectionStoryPage } from './components/CollectionStoryPage';
import { CloserLookModal } from './components/CloserLookModal';
import { QuickViewModal } from './components/QuickViewModal';
import { CartDrawer } from './components/CartDrawer';
import { NavigationDrawer } from './components/NavigationDrawer';
import { AccountModal } from './components/AccountModal';
import { SearchModal } from './components/SearchModal';
import { HERO_PRODUCTS, ALL_PRODUCTS } from './data/mockData';
import { Product, CartItem, Currency } from './types';
import { Check } from '@mynaui/icons-react';

export default function App() {
  const [cart, setCart] = useState<CartItem[]>(() => {
    try {
      const saved = localStorage.getItem('kith_cart');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  // Navigation View: 'home' | 'products' | 'product-detail' | 'about' | 'contact' | 'profile' | 'checkout' | 'collection-story'
  const [currentView, setCurrentView] = useState<'home' | 'products' | 'product-detail' | 'about' | 'contact' | 'profile' | 'checkout' | 'collection-story'>('home');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(() => {
    return ALL_PRODUCTS.find((p) => p.id === 'lengeh-cashmere-crew-knit') || ALL_PRODUCTS[0];
  });
  const [productFilter, setProductFilter] = useState<{
    gender?: 'all' | 'men' | 'women';
    collection?: string;
    category?: string;
    badge?: string;
  }>({ gender: 'all' });

  // Garderob (Saved Items / Wardrobe)
  const [garderobIds, setGarderobIds] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('lengeh_garderob');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [isMenuOpen, setIsMenuOpen] = useState<boolean>(false);
  const [isCartOpen, setIsCartOpen] = useState<boolean>(false);
  const [isAccountOpen, setIsAccountOpen] = useState<boolean>(false);
  const [isSearchOpen, setIsSearchOpen] = useState<boolean>(false);
  const [isCloserLookOpen, setIsCloserLookOpen] = useState<boolean>(false);
  const [quickViewProduct, setQuickViewProduct] = useState<Product | null>(null);
  const [currency, setCurrency] = useState<Currency>('EUR');
  const [isScrolled, setIsScrolled] = useState<boolean>(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  // Authenticated user state
  const [userPhone, setUserPhone] = useState<string | null>(() => {
    try {
      return localStorage.getItem('lengeh_user_phone') || null;
    } catch {
      return null;
    }
  });

  const [userName, setUserName] = useState<string>(() => {
    try {
      return localStorage.getItem('lengeh_user_name') || '';
    } catch {
      return '';
    }
  });

  const handleUpdateUserName = (name: string) => {
    setUserName(name);
    try {
      localStorage.setItem('lengeh_user_name', name);
    } catch {
      // ignore
    }
  };

  const handleLoginSuccess = (phone: string) => {
    setUserPhone(phone);
    setIsAccountOpen(false);
    showToast('شما با موفقیت وارد شدید');
    setCurrentView('profile');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleLogout = () => {
    setUserPhone(null);
    try {
      localStorage.removeItem('lengeh_user_phone');
    } catch {
      // ignore
    }
    setIsAccountOpen(false);
    setCurrentView('home');
    window.scrollTo({ top: 0, behavior: 'smooth' });
    showToast('از حساب کاربری خارج شدید');
  };

  const [profileSubView, setProfileSubView] = useState<'menu' | 'orders' | 'wishlist' | 'addresses' | 'personal-info'>('menu');

  const handleOpenAccount = () => {
    if (userPhone) {
      setProfileSubView('menu');
      setCurrentView('profile');
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
      setIsAccountOpen(true);
    }
  };

  // Sync cart to local storage
  useEffect(() => {
    try {
      localStorage.setItem('kith_cart', JSON.stringify(cart));
    } catch {
      // ignore
    }
  }, [cart]);

  // Scroll detection for header styling
  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 40);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const showToast = (message: string) => {
    setToastMessage(message);
    setTimeout(() => {
      setToastMessage((curr) => (curr === message ? null : curr));
    }, 3000);
  };

  const handleToggleGarderob = (product: Product) => {
    setGarderobIds((prev) => {
      const exists = prev.includes(product.id);
      const next = exists ? prev.filter((id) => id !== product.id) : [...prev, product.id];
      try {
        localStorage.setItem('lengeh_garderob', JSON.stringify(next));
      } catch {
        // ignore
      }
      showToast(
        exists
          ? `${product.name} از لیست علاقمندی‌ها حذف شد`
          : `${product.name} به لیست علاقمندی‌ها افزوده شد`
      );
      return next;
    });
  };

  const handleAddToCart = (product: Product, size: string) => {
    setCart((prev) => {
      const existing = prev.find(
        (item) => item.product.id === product.id && item.selectedSize === size
      );
      if (existing) {
        return prev.map((item) =>
          item.product.id === product.id && item.selectedSize === size
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      }
      return [...prev, { product, selectedSize: size, quantity: 1 }];
    });
    showToast(`${product.name} (سایز ${size}) به سبد خرید اضافه شد`);
  };

  const handleAddAllHeroPieces = () => {
    HERO_PRODUCTS.forEach((product) => {
      const defaultSize = product.sizes[0];
      handleAddToCart(product, defaultSize);
    });
    showToast('ست کامل استایل پاییز ۲۰۲۶ به سبد خرید اضافه شد');
  };

  const handleUpdateQuantity = (productId: string, size: string, delta: number) => {
    setCart((prev) =>
      prev
        .map((item) => {
          if (item.product.id === productId && item.selectedSize === size) {
            const newQty = item.quantity + delta;
            return newQty > 0 ? { ...item, quantity: newQty } : null;
          }
          return item;
        })
        .filter(Boolean) as CartItem[]
    );
  };

  const handleRemoveItem = (productId: string, size: string) => {
    setCart((prev) =>
      prev.filter(
        (item) => !(item.product.id === productId && item.selectedSize === size)
      )
    );
  };

  const handleNavigateToProducts = (filter?: {
    gender?: 'all' | 'men' | 'women';
    collection?: string;
    category?: string;
    badge?: string;
  }) => {
    setProductFilter({
      gender: filter?.gender || 'all',
      collection: filter?.collection || 'all',
      category: filter?.category || 'all',
      badge: filter?.badge,
    });
    setCurrentView('products');
    setIsMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleNavigateToHome = () => {
    setCurrentView('home');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleNavigateToAbout = () => {
    setCurrentView('about');
    setIsMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleNavigateToContact = () => {
    setCurrentView('contact');
    setIsMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleOpenProductDetail = (product: Product) => {
    setSelectedProduct(product);
    setCurrentView('product-detail');
    setIsMenuOpen(false);
    setIsSearchOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleProceedToCheckout = () => {
    setIsCartOpen(false);
    setCurrentView('checkout');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleOpenCollectionStory = () => {
    setCurrentView('collection-story');
    setIsMenuOpen(false);
    setIsSearchOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleOrderCompleted = (goToProfile?: boolean) => {
    setCart([]);
    try {
      localStorage.removeItem('kith_cart');
    } catch {}

    if (goToProfile) {
      if (!userPhone) {
        const phone = '۰۹۱۲۳۴۵۶۷۸۹';
        setUserPhone(phone);
        try {
          localStorage.setItem('lengeh_user_phone', phone);
        } catch {}
      }
      setProfileSubView('orders');
      setCurrentView('profile');
      window.scrollTo({ top: 0, behavior: 'smooth' });
      showToast('سفارش شما با موفقیت ثبت شد');
    } else {
      setCurrentView('home');
      window.scrollTo({ top: 0, behavior: 'smooth' });
      showToast('سفارش شما با موفقیت ثبت شد');
    }
  };

  const totalCartCount = cart.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <div dir="rtl" className="min-h-screen bg-white text-neutral-900 font-tommy relative selection:bg-black selection:text-white">
      {/* Toast Notification (Top center, single-line, light green for login success) */}
      {toastMessage && (
        <div className="fixed top-6 left-1/2 -translate-x-1/2 z-50 flex items-center justify-center pointer-events-none px-3 max-w-[95vw]">
          <div
            className={`pointer-events-auto px-4 sm:px-5 py-2.5 text-xs sm:text-[13px] font-medium shadow-xl flex items-center gap-2 whitespace-nowrap animate-in fade-in slide-in-from-top-4 duration-250 select-none ${
              toastMessage.includes('موفقیت')
                ? 'bg-[#eaf7ee] text-[#1b5e20] border border-[#bfe7ca]'
                : 'bg-black/95 text-white border border-white/20'
            }`}
            style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}
          >
            <Check className={`w-4 h-4 shrink-0 ${toastMessage.includes('موفقیت') ? 'text-[#2e7d32]' : 'text-emerald-400'}`} />
            <span className="whitespace-nowrap">{toastMessage}</span>
          </div>
        </div>
      )}

      {/* Global Header */}
      <Header
        cartCount={totalCartCount}
        onOpenMenu={() => setIsMenuOpen(true)}
        onOpenCart={() => setIsCartOpen(true)}
        onOpenAccount={handleOpenAccount}
        onOpenSearch={() => setIsSearchOpen(true)}
        onNavigateHome={handleNavigateToHome}
        isScrolled={isScrolled}
        isLightBackground={currentView === 'products' || currentView === 'product-detail' || currentView === 'about' || currentView === 'contact' || currentView === 'profile' || currentView === 'checkout' || currentView === 'collection-story'}
        currency={currency}
        onCurrencyChange={setCurrency}
      />

      <main className={currentView === 'products' || currentView === 'product-detail' || currentView === 'about' || currentView === 'contact' || currentView === 'profile' || currentView === 'checkout' || currentView === 'collection-story' ? 'pt-12 sm:pt-14' : ''}>
        {currentView === 'checkout' ? (
          /* Dedicated Address & Delivery Time Checkout Page */
          <CheckoutPage
            items={cart}
            userPhone={userPhone}
            userName={userName}
            onBackToCart={() => {
              setCurrentView('home');
              setIsCartOpen(true);
            }}
            onOrderCompleted={handleOrderCompleted}
          />
        ) : currentView === 'profile' ? (
          /* Dedicated Profile Page matching image_b4781195.png */
          <ProfilePage
            userPhone={userPhone || ''}
            userName={userName}
            onUpdateUserName={handleUpdateUserName}
            onLogout={handleLogout}
            onNavigateHome={handleNavigateToHome}
            onNavigateToProducts={handleNavigateToProducts}
            garderobIds={garderobIds}
            onOpenProductDetail={handleOpenProductDetail}
            onToggleGarderob={handleToggleGarderob}
            initialSubView={profileSubView}
          />
        ) : currentView === 'about' ? (
          /* Dedicated About Us Page (Kith About Layout) */
          <AboutPage
            onNavigateHome={handleNavigateToHome}
            onNavigateToProducts={handleNavigateToProducts}
          />
        ) : currentView === 'contact' ? (
          /* Dedicated Contact & FAQ Page */
          <ContactPage
            onNavigateHome={handleNavigateToHome}
            onNavigateToProducts={handleNavigateToProducts}
          />
        ) : currentView === 'product-detail' ? (
          /* Dedicated Luxury Product Detail Page (Toteme PDP Layout) */
          <ProductDetailPage
            product={selectedProduct}
            currency={currency}
            onBack={() => {
              setCurrentView('products');
              window.scrollTo({ top: 0, behavior: 'smooth' });
            }}
            onAddToCart={handleAddToCart}
            onUpdateQuantity={handleUpdateQuantity}
            onRemoveItem={handleRemoveItem}
            cartItems={cart}
            onSelectProduct={handleOpenProductDetail}
            garderobIds={garderobIds}
            onToggleGarderob={handleToggleGarderob}
          />
        ) : currentView === 'products' ? (
          /* Dedicated Minimalist Product List Page matching reference picture */
          <ProductListPage
            initialGender={productFilter.gender}
            initialCollection={productFilter.collection}
            initialCategory={productFilter.category}
            initialBadge={productFilter.badge}
            currency={currency}
            onBackToHome={handleNavigateToHome}
            onSelectProduct={handleOpenProductDetail}
            garderobIds={garderobIds}
            onToggleGarderob={handleToggleGarderob}
          />
        ) : currentView === 'collection-story' ? (
          /* Dedicated Collection Story & Certificate of Authenticity Page */
          <CollectionStoryPage
            onNavigateHome={handleNavigateToHome}
            onNavigateToProducts={() => handleNavigateToProducts({ gender: 'all' })}
          />
        ) : (
          /* Homepage */
          <>
            {/* Hero Section */}
            <HeroSection
              onShopNowClick={() => handleNavigateToProducts({ gender: 'men' })}
              onCloserLookClick={handleOpenCollectionStory}
              onQuickAdd={handleAddToCart}
            />

            {/* 4 Product Cards Grid matching reference photo */}
            <ProductLookbookCards
              onQuickShop={(product) => handleOpenProductDetail(product)}
              onOpenQuickView={(product) => handleOpenProductDetail(product)}
            />

            {/* Women's Editorial Section: Full-Width Photo with Same Title, Subtitle, 2 Buttons */}
            <WomenHeroSection
              onShopNowClick={() => handleNavigateToProducts({ gender: 'women' })}
              onCloserLookClick={handleOpenCollectionStory}
            />

            {/* 4 Women's Editorial Cards with the Same Vibe */}
            <WomenLookbookCards
              onQuickShop={(product) => handleOpenProductDetail(product)}
              onOpenQuickView={(product) => handleOpenProductDetail(product)}
            />
          </>
        )}

        {/* Accordion Footer matching reference photo */}
        <Footer
          onOpenCloserLook={handleOpenCollectionStory}
          onNavigateToProducts={handleNavigateToProducts}
          onNavigateToAbout={handleNavigateToAbout}
          onNavigateToContact={handleNavigateToContact}
        />
      </main>

      {/* Full-width Navigation Menu */}
      <NavigationDrawer
        isOpen={isMenuOpen}
        onClose={() => setIsMenuOpen(false)}
        onSelectCategory={() => setIsMenuOpen(false)}
        onNavigateToProducts={handleNavigateToProducts}
        onOpenCloserLook={handleOpenCollectionStory}
        currency={currency}
        onCurrencyChange={setCurrency}
        onSelectProduct={(product) => {
          setIsMenuOpen(false);
          handleOpenProductDetail(product);
        }}
        onNavigateToAbout={handleNavigateToAbout}
        onNavigateToContact={handleNavigateToContact}
      />

      <CartDrawer
        isOpen={isCartOpen}
        onClose={() => setIsCartOpen(false)}
        items={cart}
        onUpdateQuantity={handleUpdateQuantity}
        onRemoveItem={handleRemoveItem}
        onStartShopping={() => {
          setIsCartOpen(false);
          handleNavigateToProducts();
        }}
        onProceedToCheckout={handleProceedToCheckout}
      />

      <CloserLookModal
        isOpen={isCloserLookOpen}
        onClose={() => setIsCloserLookOpen(false)}
        onQuickAdd={handleAddToCart}
        onAddAllHeroPieces={handleAddAllHeroPieces}
      />

      <QuickViewModal
        product={quickViewProduct}
        onClose={() => setQuickViewProduct(null)}
        onAddToCart={handleAddToCart}
      />

      <AccountModal
        isOpen={isAccountOpen}
        onClose={() => setIsAccountOpen(false)}
        userPhone={userPhone}
        onLoginSuccess={handleLoginSuccess}
        onLogout={handleLogout}
      />

      <SearchModal
        isOpen={isSearchOpen}
        onClose={() => setIsSearchOpen(false)}
        onSelectProduct={(p) => {
          setIsSearchOpen(false);
          handleOpenProductDetail(p);
        }}
      />
    </div>
  );
}
